entries[1243010] = { ["name"] = "Untethered Sting", ["text"] = "40 yd range\n3.5 sec cast 4 sec cooldown\nFires erratic energies at an enemy every 1.3 sec for 3.8 sec, inflicting Arcane damage to enemies within 0 yards of the impact.\n\nAlso triggers Untethered Focus .\n\nUntethered Focus\n100 yd range\n\nInstant Creates a sphere of volatile Arcane energy at a location, inflicting 5 Arcane damage and knocking back targets within 5 yards.\n\nThis detonation can cause a chain reaction." }
entries[1243011] = { ["name"] = "Fury of the War God", ["text"] = "100 yd range\nInstant\nNalorakk headbutts Zul'jarra into a Concussive Shock , then commands the Echoes of Nalorakk to charge her position. These collide with the first target encountered casting Echoing Fury .\n\nAny Echo of Nalorakk that reaches Zul'jarra triggers Demoralizing Scream . Each Echo remains for one additional Fury of the War God , then vanishes." }
