entries[1243173] = { ["name"] = "Blessing: Victorious Waves", ["text"] = "Akil'zon, Loa of Victory\nPahk, Loa of the Depths\n\nThe loas of Victory and the Depths grant you 100% swim speed in water.\n\nOnly usable in Zul'Aman." }
entries[1243174] = { ["name"] = "Blessing: Victor's Presence", ["text"] = "Akil'zon, Loa of Victory\nMot'amra, Loa of Pestilence\n\nThe loas of Victory and Pestilence bless you with a 15% chance to Stun your enemy for 3 sec.\n\nDoes not work on players.\nOnly active while in Zul'Aman." }
entries[1243175] = { ["name"] = "Blessing: Packpeddle of Victory", ["text"] = "Akil'zon, Loa of Victory\nWila'ma, Loa of Travelers\n\nThe loas of Victory and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman." }
entries[1243176] = { ["name"] = "Blessing: Victory Through Subterfuge", ["text"] = "Akil'zon, Loa of Victory\nShadra, Loa of Subterfuge\n\nWhile in combat, the loas of Victory and Subterfuge increase your Haste by 1% every 1 second up to 15%. Decreases while out of combat.\n\nOnly active while in Zul'Aman." }
entries[1243177] = { ["name"] = "Blessing: Abundant Rush", ["text"] = "Akil'zon, Loa of Victory\nDundun, Loa of Abundance\n\nThe loas of Victory and Abundance vastly increase your Profession Gathering and Crafting speed by granting you +15 Deftness and +50 Crafting Speed.\n\nOnly active while in Zul'Aman." }
entries[1243178] = { ["name"] = "Blessing: Victory at Any Cost", ["text"] = "Akil'zon, Loa of Victory\nPuul, Loa of Peril\n\nThrough the loas of Victory and Peril, you gain 100% Movement Speed for 3 sec whenever you slay an enemy.\n\nBut you also take 100% more Damage from the next source.\n\nOnly active while in Zul'Aman." }
entries[1243179] = { ["name"] = "Blessing: Victorious Growth", ["text"] = "Akil'zon, Loa of Victory\nOe, Loa of Growth\n\nThrough the loas of Victory and Forests, you gain 25% Weapon Attack Speed.\n\nOnly active while in Zul'Aman." }
entries[1243184] = { ["name"] = "Blessing: Neverending Hunt", ["text"] = "Halazzi, Loa of the Hunt\nKulzi, Loa of Medicine\n\nThrough the loas of the Hunt and of Medicine, you regain 5% health every time an enemy is slain.\n\nOnly active while in Zul'Aman." }
entries[1243185] = { ["name"] = "Blessing: Hunt for Simplicity", ["text"] = "Halazzi, Loa of the Hunt\nFilo, Loa of Children\n\n5% chance on hit to receive:\n\nMoment of Simplicity :\nThe loas of the Hunt and Children increase your Spell, Attack, Ranged, and Healing Power by 100% for 3 sec.\n\nOnly active while in Zul'Aman." }
entries[1243186] = { ["name"] = "Blessing: Devoted Adaptation", ["text"] = "Halazzi, Loa of the Hunt\nPahk, Loa of the Depths\n\nThe loas of the Hunt and of the Depths grants your lungs 300% more breath when underwater.\n\nOnly active while in Zul'Aman." }
entries[1243187] = { ["name"] = "Blessing: Guaranteed Yield", ["text"] = "Halazzi, Loa of the Hunt\nMot'amra, Loa of Pestilence\n\nThe loas of Victory and Pestilence bless you with a 15% chance to poison your enemy, inflicting 3 Nature damage every 1 sec for 4 sec.\n\nOnly active while in Zul'Aman." }
entries[1243188] = { ["name"] = "Light Madness" }
entries[1243189] = { ["name"] = "Blessing: Packpeddle of the Hunt", ["text"] = "Halazzi, Loa of the Hunt\nWila'ma, Loa of Travelers\n\nThe loas of the Hunt and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman." }
entries[1243190] = { ["name"] = "Blessing: The Cunning Hunt", ["text"] = "Halazzi, Loa of the Hunt\nShadra, Loa of Subterfuge\n\nWhile in combat, the loas of the Hunt and Subterfuge increase your critical strike chance by 1% every 1 second up to 15%. Decreases while out of combat.\n\nOnly active while in Zul'Aman." }
entries[1243191] = { ["name"] = "Blessing: Guide of the Harvest", ["text"] = "Halazzi, Loa of the Hunt\nDundun, Loa of Abundance\n\nThe loas of the Hunt and Abundance bless your Professions Gathering with a 15% chance to summon a Visage of Dundun every time you successfully harvest using Mining, Herbalism, Skinning, or Fishing." }
entries[1243192] = { ["name"] = "Blessing: Predator's Gamble", ["text"] = "Halazzi, Loa of the Hunt\nPuul, Loa of Peril\n\nThrough the loas of the Hunt and Peril, you have a 25% chance on hit to deal 100% more damage.\n\nBut you also have a 25% chance on hit to deal -50% less damage.\n\nOnly active while in Zul'Aman." }
entries[1243193] = { ["name"] = "Blessing: Patient Hunter", ["text"] = "Halazzi, Loa of the Hunt\nOe, Loa of Growth\n\nThrough the loas of the Hunt and Forests, you gain a 5% chance for your attack to deal 500% damage.\n\nOnly active while in Zul'Aman." }
entries[1243194] = { ["name"] = "Blessing: Flame of Vitality", ["text"] = "Jan'alai, Loa of Fire\nKulzi, Loa of Medicine\n\nThe loas of Fire and Medicine increase your Spell Power by 20% while your health is above 90%.\n\nOnly active while in Zul'Aman." }
entries[1243195] = { ["name"] = "Blessing: Flowing Flame", ["text"] = "Jan'alai, Loa of Fire\nFilo, Loa of Children\n\nThe loas of Fire and Childhood bless you with a 2% increase to Intelligence with every successful spell cast for 10 sec. Stacks up to 10 times.\n\nOnly active while in Zul'Aman." }
entries[1243196] = { ["name"] = "Blessing: Buoyant Flame", ["text"] = "Jan'alai, Loa of Fire\nPahk, Loa of the Depths\n\nThe loas of Fire and the Depths bless you with Waterwalking.\n\nOnly active while in Zul'Aman." }
entries[1243197] = { ["name"] = "Blessing: Ensorcelling Flame", ["text"] = "Jan'alai, Loa of Fire\nMot'amra, Loa of Pestilence\n\nThe loas of Fire and Pestilence bless you with a 5% chance to Charm your enemy for 5 sec, forcing them to fight other hostile foes on your behalf.\n\nOnly active while in Zul'Aman." }
entries[1243198] = { ["name"] = "Blessing: Packpeddle of Fire", ["text"] = "Jan'alai, Loa of Fire\nWila'ma, Loa of Travelers\n\nThe loas of Fire and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman." }
entries[1243200] = { ["name"] = "Blessing: Creeping Flame", ["text"] = "Jan'alai, Loa of Fire\nShadra, Loa of Subterfuge\n\nWhile in combat, the loas of Fire and Subterfuge increase your Spell Power by 1% every 1 second up to 25%. Decreases while out of combat.\n\nOnly active while in Zul'Aman." }
entries[1243201] = { ["name"] = "Blessing: Harvest Haste", ["text"] = "Jan'alai, Loa of Fire\nDundun, Loa of Abundance\n\nThe loas of the Hunt and Abundance increase your Movement Speed by 100% for 5 sec whenever you gather reagents via Mining, Herbalism, Skinning, or Fishing.\n\nOnly active while in Zul'Aman." }
entries[1243202] = { ["name"] = "Blessing: Ravenous Glass", ["text"] = "Jan'alai, Loa of Fire\nPuul, Loa of Peril\n\nThrough the loas of Victory and Peril, you gain 100% Spell Power\n\nBut you will also receive 100% more damage from all sources.\n\nOnly active while in Zul'Aman." }
entries[1243203] = { ["name"] = "Blessing: Everthrive Flame", ["text"] = "Jan'alai, Loa of Fire\nOe, Loa of Growth\n\nThrough the loas of Fire and Growth, you gain a 15% increase to Intelligence.\n\nOnly active while in Zul'Aman." }
entries[1243204] = { ["name"] = "Blessing: War of Attrition", ["text"] = "Nalorakk, Loa of War\nKulzi, Loa of Medicine\n\nThrough the loas of War and of Medicine, you are healed 50% whenever your health is brought below 15%.\n\nCannot occur more than once every 10 min.\n\nOnly active while in Zul'Aman." }
entries[1243205] = { ["name"] = "Blessing: War Against Threats", ["text"] = "Nalorakk, Loa of War\nFilo, Loa of Children\n\nWhen Health is below 50%, the loas of War and Children summon a Grand Kapara Guard to fight with you for 2 min.\n\nOnly usable in Zul'Aman." }
entries[1243206] = { ["name"] = "Blessing: War on the Currents", ["text"] = "Nalorakk, Loa of War\nPahk, Loa of the Depths\n\nThe loas of War and the Depths grant you the ability to walk upon any body of water's floor.\n\nOnly usable in Zul'Aman." }
entries[1243207] = { ["name"] = "Blessing: War-Spoiled", ["text"] = "Nalorakk, Loa of War\nMot'amra, Loa of Pestilence\n\nThe loas of War and Pestilence bless you with a 15% chance to pierce a target's armor, increasing Physical damage taken by 30% for 10 sec. This effect stacks up to 5 charges.\n\nOnly active while in Zul'Aman." }
entries[1243208] = { ["name"] = "Blessing: Packpeddle of War", ["text"] = "Nalorakk, Loa of War\nWila'ma, Loa of Travelers\n\nThe loas of War and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman." }
entries[1243209] = { ["name"] = "Blessing: Wartime Preparations", ["text"] = "Nalorakk, Loa of War\nShadra, Loa of Subterfuge\n\nWhile in combat, the loas of War and Subterfuge increase your Health by 1% and Armor by 2% every 1 second (Maximum of 25 stacks). Decreases while out of combat.\n\nOnly active while in Zul'Aman." }
entries[1243210] = { ["name"] = "Blessing: Abundance Permanence", ["text"] = "Nalorakk, Loa of War\nDundun, Loa of Abundance\n\nWhenever you gather reagents via Mining, Herbalism, Skinning, or Fishing, the Loas of War and Abundance heal you by 15% and reduce damage taken by 50% until you're damaged next.\n\nOnly active while in Zul'Aman." }
entries[1243211] = { ["name"] = "Blessing: Reckless Feast", ["text"] = "Nalorakk, Loa of War\nPuul, Loa of Peril\n\nThrough the loas of War and Peril, you gain 25% Leech.\n\nBut you also take 25% more damage from all sources.\n\nOnly active while in Zul'Aman." }
entries[1243213] = { ["name"] = "Blessing: Command Experience", ["text"] = "Nalorakk, Loa of War\nOe, Loa of Growth\n\nThrough the loas of War and Growth, you gain 10% more Strength and Stamina.\n\nOnly active while in Zul'Aman." }
