entries[1243582] = { ["name"] = "Dusk Grimlynx", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Famously adept at hunting at dusk as the light of dusk blends this grimlynx's foliage with its surroundings.\"\nQuest:\nHistory Lesson\nZone:\nHarandar" }
entries[1243583] = { ["name"] = "Suffocating Void" }
entries[1243585] = { ["name"] = "Overwhelming Onslaught", ["text"] = "3 sec cast\nNalorakk unleashes a devastating set of attacks on all players, inflicting 315193 Physical damage every 1 sec for 3 sec. These attacks ignore armor.\n\nThe final hit stuns Zul'Jarra and knocks all players back. Nalorakk then targets Zul'Jarra with Forceful Slam ." }
entries[1243586] = { ["name"] = "Unstable Void Essence", ["text"] = "Instant 3 sec cooldown\nDegentrius launches unstable void energy that bounces to 4 locations, inflicting 96982 Shadow damage to any player at the point of impact.\n\nIf no player is in the area the unstable void essence erupts in Void Destruction ." }
entries[1243587] = { ["name"] = "Harpoon", ["text"] = "Instant\nMuro'jin hurls a harpoon at a player, rooting them in place for 4 sec and pulling himself to them.\n\nUpon arrival, Muro'jin inflicts 15 Physical damage to players within 5 yards." }
entries[1243588] = { ["name"] = "Unstable Void Essence", ["text"] = "100 yd range\nInstant\nDegentrius launches unstable void energy that bounces to 4 locations, inflicting 96982 Shadow damage to any player at the point of impact.\n\nIf no player is in the area the unstable void essence erupts in Void Destruction ." }
entries[1243589] = { ["name"] = "Void-Forged Overseer", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"After the Sepulcher of the First Ones was opened, this construct of the First Ones was stolen by the brokers and sold to the ethereals in a transaction at the Veiled Market. Under the ethereals' ingenious modifications, it integrated the mysteries of the Aether, gliding through the air with extraordinary elegance, leaving behind a trail of shimmering stardust.\"\nPromotion" }
entries[1243590] = { ["name"] = "Overwhelming Onslaught", ["text"] = "100 yd range\nInstant\nNalorakk swipes repeatedly, obliterating his primary target for 4 sec, inflicting 387930 Physical damage every 1 sec and increasing Overwhelming Onslaught damage taken by 50% for 5 sec. This effect stacks." }
