entries[1243593] = { ["name"] = "Fierce Grimlynx", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This grimlynx has seen many battles against the creatures in the Rift of Aln.\"\nVendor:\nNaynar\nZone:\nHarandar\nCost:\n6000" }
