entries[1243597] = { ["name"] = "Rootstalker Grimlynx", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"With fur to match the deep roots and armor to match the vast foliage, these Grimlynx are equipped to be some of the ultimate hunters of Harandar.\"\nDrop:\nHarandar Rare Creatures" }
entries[1243598] = { ["name"] = "Ivory Grimlynx", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Ivory grimlynxes have a strong independent streak. It takes an especially brave Haranir to ride them.\"\nAchievement:\nAllied Race: Haranir\nCategory:\nMidnight" }
